-- Phase 13: versioned policy publication and immutable consent evidence.
create table public.legal_documents(id uuid primary key default gen_random_uuid(),document_type text not null check(document_type in('terms','privacy','refunds','acceptable_use')),version text not null,title text not null,effective_at timestamptz not null,status text not null check(status in('draft','active','retired')),content_hash text,created_at timestamptz not null default now(),unique(document_type,version));
create table public.user_consents(id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,terms_version text not null,privacy_version text not null,accepted_at timestamptz not null,source text not null default 'signup',ip_hash text,user_agent text,unique(user_id,terms_version,privacy_version,source));
alter table public.legal_documents enable row level security;alter table public.user_consents enable row level security;
create policy "active legal documents public" on public.legal_documents for select using(status='active');create policy "legal documents admin manage" on public.legal_documents for all using(public.is_platform_admin()) with check(public.is_platform_admin());create policy "consent owner read" on public.user_consents for select using(user_id=auth.uid());create policy "consent admin read" on public.user_consents for select using(public.is_platform_admin());
insert into public.legal_documents(document_type,version,title,effective_at,status) values('terms','2026-08-05','Marketplace Terms of Use','2026-08-05','active'),('privacy','2026-08-05','Privacy Notice','2026-08-05','active'),('refunds','2026-08-05','Refund and Dispute Policy','2026-08-05','active'),('acceptable_use','2026-08-05','Acceptable Use Policy','2026-08-05','active') on conflict do nothing;
create or replace function public.record_signup_consent() returns trigger language plpgsql security definer set search_path=public as $$begin if new.raw_user_meta_data->>'terms_version' is not null then insert into public.user_consents(user_id,terms_version,privacy_version,accepted_at) values(new.id,new.raw_user_meta_data->>'terms_version',new.raw_user_meta_data->>'privacy_version',coalesce((new.raw_user_meta_data->>'terms_accepted_at')::timestamptz,now())) on conflict do nothing;end if;return new;end;$$;
drop trigger if exists zz_record_signup_consent on auth.users;create trigger zz_record_signup_consent after insert on auth.users for each row execute function public.record_signup_consent();
